import{_ as o,l as a,o as n,b as i,q as t,d as p,f as S,m as l}from"./chunks/framework.Tf23FRXt.js";const h=JSON.parse('{"title":"间歇灵泉哈姆岛","description":"","frontmatter":{},"headers":[{"level":2,"title":"进场 ~ BOSS 1","slug":"进场-boss-1","link":"#进场-boss-1","children":[{"level":3,"title":"BOSS 1 林巴克尔","slug":"boss-1-林巴克尔","link":"#boss-1-林巴克尔","children":[]}]},{"level":2,"title":"BOSS 1 ~ BOSS 2","slug":"boss-1-boss-2","link":"#boss-1-boss-2","children":[{"level":3,"title":"BOSS 2 阿尔卡斯","slug":"boss-2-阿尔卡斯","link":"#boss-2-阿尔卡斯","children":[]}]},{"level":2,"title":"BOSS 2 ~ BOSS 3","slug":"boss-2-boss-3","link":"#boss-2-boss-3","children":[{"level":3,"title":"BOSS 3 八足巨妖","slug":"boss-3-八足巨妖","link":"#boss-3-八足巨妖","children":[]}]}],"relativePath":"duty/822.htm.md","filePath":"duty/822.md","lastUpdated":1791101830000}'),d={name:"duty/822.htm.md"};function r(b,s,_,O,m,B){const e=a("Role");return n(),i("div",null,[s[2]||(s[2]=t('<h1 id="间歇灵泉哈姆岛" tabindex="-1">间歇灵泉哈姆岛</h1><h2 id="进场-boss-1" tabindex="-1">进场～BOSS 1</h2><p>可以跑到头拉一波，一共 2 波。</p><h3 id="boss-1-林巴克尔" tabindex="-1">BOSS 1 林巴克尔</h3><p>开场 AOE 后不久转身读条<mark>怒潮吐息</mark>，正面半场 AOE，需要去 BOSS 身后躲避。</p><p>场地上出现小冰块后，不久会以冰块为圆心，产生大约和 BOSS 直径相同的圆形范围 AOE。第二次召唤冰块为大冰块，范围约为 BOSS 直径的两倍。</p><p>分散分摊会紧接半场 AOE，注意躲避。</p><p>最后一次冰山是同时召唤大小冰山，但是小冰山先炸，大冰山后炸，观察顺序躲避即可。</p><h2 id="boss-1-boss-2" tabindex="-1">BOSS 1 ~ BOSS 2</h2><p>每段都可以拉一波。</p><h3 id="boss-2-阿尔卡斯" tabindex="-1">BOSS 2 阿尔卡斯</h3>',11)),p("p",null,[s[0]||(s[0]=S("出啥躲啥就行，BOSS 跳到场边后，场地出现紫线，实际范围比预兆略宽，",-1)),l(e,{name:"tank"}),l(e,{name:"melee"}),s[1]||(s[1]=S("近战尽可能找大的空隙躲避，实际预兆（深紫色区域）出现后，大约还有 1s 左右调整时间。",-1))]),s[3]||(s[3]=t('<p>后半段场地变小，判定速度加快，但没有新机制。</p><h2 id="boss-2-boss-3" tabindex="-1">BOSS 2 ~ BOSS 3</h2><p>每个桥头前刹一脚打掉即可。</p><h3 id="boss-3-八足巨妖" tabindex="-1">BOSS 3 八足巨妖</h3><p>场地为 5 个连在一起的小圆平台，读条<mark>八足重击</mark>时，平台内外会出现章鱼触手，没有触手的平台是安全的。</p><p>读条<mark>吐水</mark>时，平台上同时出现蓝色水球预兆，站在任意两个台子的连接处躲避。</p><p>读条<mark>怒潮吐息</mark>时，为 BOSS 面向正面半场 AOE，沿着 BOSS 环跑到侧后方躲避（目标环侧面有一个小箭头，该箭头位置为前后的分界点）</p><p>读条<mark>念力</mark>同时 BOSS 连线场边大石块，石块会连线场内的平台，找到没有连线的平台躲避。</p><p>之后会有一次触手 + 吐息的组合技，最小可能只有 1/4 个平台是安全的，同时安全区可能会覆盖近战攻击范围，注意躲避。</p>',9))])}const u=o(d,[["render",r]]);export{h as __pageData,u as default};
